      vitamin_c_ascorbate: { morning: 1000, unit: 'мг' },
      bromelain: { morning: 1300, unit: 'GDU/G' },
      bromantane: { morning: 50, unit: 'мг' },
      fasoracetam: { morning: 100, unit: 'мг' },
      agmatine: { morning: 1000, unit: 'мг' },
      bergamot: { morning: 1, unit: 'таб' },
